#include <vector>
#include <iostream>
#include <algorithm>

int calculate_max_subsequence(const std::vector<int>& sequence, int start_idx, int max_diff) {
    int length = 1;
    for (int idx = start_idx + 1; idx < (int)sequence.size(); ++idx) {
        if (sequence[idx] - sequence[start_idx] > max_diff)
            break;
        ++length;
    }
    return length;
}

int main() {
    std::vector<int> sequence;
    int total_elements, max_time_allowed;
    std::cin >> total_elements;
    for (int i = 0; i < total_elements; ++i) {
        int val;
        std::cin >> val;
        sequence.push_back(val);
    }
    std::cin >> max_time_allowed;
    std::sort(sequence.begin(), sequence.end());
    int max_subseq = 0;
    for (int i = 0; i < (int)sequence.size(); ++i) {
        int length = calculate_max_subsequence(sequence, i, max_time_allowed);
        if (length > max_subseq)
            max_subseq = length;
    }
    std::cout << max_subseq << "\n";
}
